from __future__ import annotations

import asyncio
from typing import Any

import pytest
import llm_router
import tests.llm_router.bdd._support as bdd_support
import tests.llm_router.support.builders as builders

pytestmark = pytest.mark.verification_kind("unit")


def _make_router() -> Any:
    """Build a test router instance using available support builders or public types."""
    for factory_name in (
        "build_router",
        "make_router",
        "build_test_router",
        "create_router",
    ):
        factory = getattr(builders, factory_name, None) or getattr(
            bdd_support, factory_name, None
        )
        if callable(factory):
            try:
                return factory()
            except TypeError:
                pass
            except Exception:
                pass

    if hasattr(builders, "RouterBuilder"):
        try:
            return builders.RouterBuilder().build()
        except Exception:
            pass

    spec_candidates = [
        getattr(builders, "build_spec", lambda: None)(),
        getattr(builders, "build_route", lambda: None)(),
        "test/model",
    ]
    for spec in spec_candidates:
        if spec is None:
            continue
        for factory_name in ("build_router", "make_router", "build_test_router"):
            factory = getattr(builders, factory_name, None)
            if callable(factory):
                try:
                    return factory(spec)
                except Exception:
                    pass

    router_cls = getattr(llm_router, "LLMRouter", None) or getattr(
        llm_router, "Router", None
    )
    if router_cls is not None:
        for spec in spec_candidates:
            if spec is None:
                continue
            try:
                return router_cls(spec)
            except Exception:
                pass

    raise RuntimeError("Could not construct a test router from builders or llm_router")


def _extract_all_traces(response: Any) -> list[Any]:
    """Extract all routing attempt traces from a router response."""
    if hasattr(response, "traces") and response.traces:
        traces_list = list(response.traces)
        if hasattr(response, "final_trace") and response.final_trace is not None:
            if response.final_trace not in traces_list:
                traces_list.append(response.final_trace)
        return traces_list
    if hasattr(response, "attempts") and response.attempts:
        return list(response.attempts)
    if hasattr(response, "final_trace") and response.final_trace is not None:
        traces_list = list(getattr(response, "traces", []))
        if response.final_trace not in traces_list:
            traces_list.append(response.final_trace)
        return traces_list
    return []


@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
@pytest.mark.asyncio
async def test_async_provider_execution_ready_route_matches_sync() -> None:
    content = "Ping text prompt"
    if hasattr(builders, "build_text_content"):
        try:
            content = builders.build_text_content()
        except Exception:
            pass
    elif hasattr(builders, "build_content"):
        try:
            content = builders.build_content()
        except Exception:
            pass

    # Synchronous baseline
    sync_router = _make_router()
    sync_res = sync_router.query(content)

    # Asynchronous execution under test
    async_router = _make_router()
    runtime = getattr(async_router, "_runtime", async_router)

    recorded_calls: list[Any] = []
    orig_call = getattr(runtime, "_call_async_with_timeout", None)
    if callable(orig_call):
        async def _spy_call(request: Any, *args: Any, **kwargs: Any) -> Any:
            recorded_calls.append(request)
            return await orig_call(request, *args, **kwargs)

        runtime._call_async_with_timeout = _spy_call

    async_res = await async_router.aquery(content)

    # 1. Check provider was invoked once on the ready route
    if recorded_calls:
        assert len(recorded_calls) == 1
        called_route = getattr(recorded_calls[0], "route", None)
        if hasattr(runtime, "route_plan") and runtime.route_plan:
            expected_route = runtime.route_plan[0]
            if called_route is not None:
                assert called_route == expected_route

    executor = getattr(runtime, "_executor", None)
    if executor is not None:
        if hasattr(executor, "calls"):
            assert len(executor.calls) == 1
        elif hasattr(executor, "call_count"):
            assert executor.call_count == 1

    # 2. Check the response carries a single successful attempt trace without blocked or fallback entries
    async_traces = _extract_all_traces(async_res)
    assert len(async_traces) == 1, f"Expected 1 trace, found {len(async_traces)}"

    single_trace = async_traces[0]
    assert getattr(single_trace, "error", None) is None
    assert getattr(single_trace, "status", "success") != "blocked"
    assert not getattr(single_trace, "blocked", False)

    assert not getattr(async_res, "fallback_occurred", False)
    if hasattr(async_res, "traces") and hasattr(async_res, "final_trace"):
        assert len(async_res.traces) == 0

    # 3. Check that the async response matches the sync result
    sync_traces = _extract_all_traces(sync_res)
    assert len(async_traces) == len(sync_traces) == 1
    assert getattr(single_trace, "route", None) == getattr(sync_traces[0], "route", None)
    assert getattr(single_trace, "error", None) == getattr(sync_traces[0], "error", None)

    if hasattr(async_res, "text") and hasattr(sync_res, "text"):
        assert async_res.text == sync_res.text
    elif hasattr(async_res, "content") and hasattr(sync_res, "content"):
        assert async_res.content == sync_res.content

    if hasattr(async_res, "fallback_occurred") and hasattr(sync_res, "fallback_occurred"):
        assert async_res.fallback_occurred == sync_res.fallback_occurred
